package com.smarthub.plus;
import org.json.*;
import java.util.*;
/** Allowlisted settings exchange; activation flags, PINs and credentials are never imported. */
public final class CommunityPackage {
 public static JSONArray mergeRecommendations(JSONArray old,JSONArray added)throws JSONException{JSONArray merged=new JSONArray();Set<String> keys=new HashSet<>();for(JSONArray batch:new JSONArray[]{old,added}){if(batch==null)continue;for(int j=0;j<batch.length()&&merged.length()<200;j++){JSONObject item=batch.optJSONObject(j);if(item==null)continue;String key=item.optString("title").trim().toLowerCase(Locale.ROOT)+"|"+item.optString("url").trim();if(keys.add(key))merged.put(item);}}return merged;}
 private static final Set<String> STRINGS=new HashSet<>(Arrays.asList("overlay_text_value","prayer_city","prayer_country"));
 private static final Set<String> INTS=new HashSet<>(Arrays.asList("overlay_text_font","overlay_caption_font"));
 public static JSONObject safeSettings(JSONObject input)throws JSONException{JSONObject out=new JSONObject();if(input==null)return out;Iterator<String> keys=input.keys();while(keys.hasNext()){String key=keys.next();Object value=input.opt(key);if(STRINGS.contains(key)&&value instanceof String){String s=(String)value;if(s.length()>2000)throw new JSONException("Setting text too long");out.put(key,s);}else if(INTS.contains(key)&&value instanceof Number)out.put(key,Math.max(12,Math.min(56,((Number)value).intValue())));else if("overlay_text_scroll".equals(key)&&value instanceof Boolean)out.put(key,value);else if("subtitle_offset".equals(key)&&value instanceof Number)out.put(key,Math.max(-10_800_000L,Math.min(10_800_000L,((Number)value).longValue())));else if(key.matches("overlay_(logo|mask|text|caption)_(x|y|w|h)")&&value instanceof Number)out.put(key,Math.max(0,Math.min(100,((Number)value).intValue())));}return out;}
 public static JSONObject validate(String json)throws JSONException{if(json.length()>12*1024*1024)throw new JSONException("Package too large");JSONObject root=new JSONObject(json);if(!"SmartHubPlusShare".equals(root.optString("format"))||root.optInt("version")!=1)throw new JSONException("Unsupported IRAQhub package");root.put("settings",safeSettings(root.optJSONObject("settings")));JSONArray input=root.optJSONArray("subtitle_timings"),safe=new JSONArray();if(input!=null){if(input.length()>100)throw new JSONException("Too many subtitle timings");for(int n=0;n<input.length();n++){JSONObject r=input.getJSONObject(n);String movie=r.optString("movie"),file=r.optString("file"),source=r.optString("source"),name=r.optString("name");if(movie.isEmpty()||movie.length()>300||file.isEmpty()||file.length()>512||source.length()>60||name.length()>250||!(r.opt("offset") instanceof Number))throw new JSONException("Invalid subtitle timing identity");long offset=r.getLong("offset");if(offset< -3600000||offset>3600000)throw new JSONException("Invalid subtitle timing offset");safe.put(new JSONObject().put("movie",movie).put("file",file).put("source",source).put("name",name).put("offset",offset));}}root.put("subtitle_timings",safe);return root;}
 private CommunityPackage(){}
}
